import {price} from '../catalog/price.mjs';

export const total = rows => {
  let sum = 0;

  for (const row of rows) {
    const quantity = row?.quantity;

    if (!Number.isSafeInteger(quantity) || quantity <= 0) {
      throw new RangeError('quantity must be a positive safe integer');
    }

    const lineTotal = price(row?.product) * quantity;
    if (!Number.isSafeInteger(lineTotal)) {
      throw new RangeError('line total must be a safe integer');
    }

    sum += lineTotal;
    if (!Number.isSafeInteger(sum)) {
      throw new RangeError('cart total must be a safe integer');
    }
  }

  return sum;
};

