import assert from 'node:assert/strict';
import {price} from './catalog/price.mjs';
import {total} from './cart/total.mjs';
import {label} from './display/label.mjs';

// Issue A: prices are nonnegative safe integers.
assert.equal(price({cents: 0}), 0);
assert.equal(price({cents: Number.MAX_SAFE_INTEGER}), Number.MAX_SAFE_INTEGER);

for (const product of [
  undefined,
  {},
  {cents: -1},
  {cents: 1.5},
  {cents: Number.MAX_SAFE_INTEGER + 1},
  {cents: Infinity},
  {cents: NaN},
  {cents: '20'},
]) {
  assert.throws(() => price(product), RangeError);
}

// Issue B: quantities are positive safe integers and totals remain safe.
assert.equal(total([]), 0);
assert.equal(total([{product: {cents: 20}, quantity: 3}]), 60);
assert.equal(total([
  {product: {cents: 20}, quantity: 3},
  {product: {cents: 5}, quantity: 4},
]), 80);
assert.equal(total([
  {product: {cents: Number.MAX_SAFE_INTEGER}, quantity: 1},
]), Number.MAX_SAFE_INTEGER);
assert.equal(total([
  {product: {cents: 0}, quantity: Number.MAX_SAFE_INTEGER},
]), 0);

for (const quantity of [
  undefined,
  0,
  -1,
  1.5,
  Number.MAX_SAFE_INTEGER + 1,
  Infinity,
  NaN,
  '2',
]) {
  assert.throws(
    () => total([{product: {cents: 20}, quantity}]),
    RangeError,
  );
}

assert.throws(
  () => total([{product: {cents: Number.MAX_SAFE_INTEGER}, quantity: 2}]),
  RangeError,
);
assert.throws(
  () => total([
    {product: {cents: Number.MAX_SAFE_INTEGER}, quantity: 1},
    {product: {cents: 1}, quantity: 1},
  ]),
  RangeError,
);
assert.throws(
  () => total([{product: {cents: -1}, quantity: 1}]),
  RangeError,
);

// Issue C: only one is singular.
assert.equal(label(0), '0 items');
assert.equal(label(1), '1 item');
assert.equal(label(2), '2 items');

for (const n of [-1, 1.5, Infinity, NaN, '1']) {
  assert.throws(() => label(n), RangeError);
}
